"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { useSearchParams } from "next/navigation";
import { apiUrl, endpoint, getJson } from "@/lib/api";
import { buildNetworkReport } from "@/lib/networkReport";
import {
  headlineChip,
  maxSourceCalls,
  perMinute,
  rateBandLabel,
  ratePosition,
  riskBadge,
  riskLabel,
  riskReasons,
  shortDuration,
  sourceState,
  stabilityTone,
  statusMixLabel,
  timelineScale,
  usageTone,
  usageVerdict,
} from "@/lib/apiUsage";
import type { ApiSourceUsage, ApiUsagePayload, NetworkDiagnosticsPayload } from "@/lib/types";

/**
 * Sin auto-recarga: ni ``setInterval`` ni ``revalidateOnFocus``. El medidor se
 * lee al abrir el diálogo y cuando el usuario pulsa «Recargar». El endpoint es
 * RAM y no cuesta peticiones, pero el refresco tampoco debe ser invisible.
 */
function toneText(tone: string): string {
  if (tone === "bad") return "text-coral";
  if (tone === "warn") return "text-gold";
  return "text-mint";
}

function toneBg(tone: string): string {
  if (tone === "bad") return "bg-coral";
  if (tone === "warn") return "bg-gold";
  return "bg-mint";
}

type CopyState = "idle" | "loading" | "done" | "error";

/**
 * Copia al portapapeles la bitácora persistente de red en Markdown.
 * El panel mide RAM (mismo proceso); la auditoría necesita el fichero.
 */
function CopyNetworkReportButton() {
  const [state, setState] = useState<CopyState>("idle");
  const timer = useRef<number | null>(null);

  useEffect(() => {
    return () => {
      if (timer.current) window.clearTimeout(timer.current);
    };
  }, []);

  const flash = (next: CopyState) => {
    setState(next);
    if (timer.current) window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setState("idle"), 2200);
  };

  const copy = async () => {
    if (state === "loading") return;
    setState("loading");
    try {
      const payload = await getJson<NetworkDiagnosticsPayload>(apiUrl("/api/diagnostics/network"));
      const text = buildNetworkReport(payload);
      if (!navigator.clipboard?.writeText) throw new Error("El navegador no permite el portapapeles.");
      await navigator.clipboard.writeText(text);
      flash("done");
    } catch {
      flash("error");
    }
  };

  const label =
    state === "done" ? "¡Copiado!" : state === "error" ? "No se pudo copiar" : state === "loading" ? "Copiando…" : "Copiar reporte para IA";

  return (
    <button
      type="button"
      className="btn btn-secondary !px-2.5 !py-1 text-xs"
      onClick={() => void copy()}
      disabled={state === "loading"}
      title="Copia la bitácora .cache/network_logs.jsonl como Markdown para pegarla en una IA"
      aria-live="polite"
    >
      <span className={state === "done" ? "text-mint" : state === "error" ? "text-coral" : undefined}>{label}</span>
    </button>
  );
}

function Stat({
  label,
  value,
  hint,
  tone = "text-ink",
}: {
  label: string;
  value: string;
  hint?: string;
  tone?: string;
}) {
  return (
    <div className="rounded-xl border border-[color:var(--line)] bg-[color:var(--surface-strong)] px-3 py-2.5">
      <p className="metric-label">{label}</p>
      <p className={`metric-value mt-1 text-lg ${tone}`}>{value}</p>
      {hint ? <p className="mt-0.5 text-[11px] leading-4 text-faint">{hint}</p> : null}
    </div>
  );
}

function RateGauge({ perMinuteValue }: { perMinuteValue: number }) {
  const position = ratePosition(perMinuteValue);
  return (
    <div className="mt-3">
      <div className="speedo" role="img" aria-label={`${perMinute(perMinuteValue)} de ritmo actual`}>
        <span className="speedo__seg speedo__seg--good" />
        <span className="speedo__seg speedo__seg--calm" />
        <span className="speedo__seg speedo__seg--warn" />
        <span className="speedo__seg speedo__seg--bad" />
        <span className="speedo__marker" style={{ left: `${position * 100}%` }} />
      </div>
      <div className="mt-1.5 flex justify-between text-[10px] font-semibold uppercase tracking-[0.08em] text-faint">
        <span>0</span>
        <span>30 bajo</span>
        <span>60 normal</span>
        <span>100 alto</span>
        <span>160+</span>
      </div>
    </div>
  );
}

function Timeline({ usage }: { usage: ApiUsagePayload }) {
  const points = usage.timeline || [];
  const scale = timelineScale(points);
  return (
    <div className="mt-2 rounded-xl border border-[color:var(--line)] bg-[color:var(--surface-strong)] p-3">
      <div className="flex items-baseline justify-between gap-2">
        <p className="text-sm font-semibold text-ink">Últimos 12 minutos</p>
        <span className="text-[11px] text-faint">llamadas por minuto</span>
      </div>
      <div className="mt-2 flex h-16 items-end gap-1">
        {points.map((point) => {
          const height = Math.max(3, Math.round((point.calls / scale) * 100));
          return (
            <div key={point.minutes_ago} className="group relative flex h-full flex-1 items-end">
              <span
                className={`w-full rounded-t-[3px] ${point.calls > 0 ? "bg-mint/70" : "bg-[color:var(--line)]"}`}
                style={{ height: `${height}%` }}
                title={`${point.label}: ${point.calls} llamadas`}
              />
            </div>
          );
        })}
      </div>
      <div className="mt-1 flex justify-between text-[10px] text-faint">
        <span>hace 12 min</span>
        <span>ahora</span>
      </div>
    </div>
  );
}

function SourceRow({ row, peak }: { row: ApiSourceUsage; peak: number }) {
  const state = sourceState(row);
  const width = Math.max(2, Math.round(((row.calls_10m || 0) / peak) * 100));
  return (
    <li className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-3 px-3 py-2.5">
      <div className="min-w-0">
        <div className="flex items-baseline justify-between gap-2">
          <span className="truncate text-sm font-medium text-ink">{row.label}</span>
          <span className="font-mono text-xs tabular-nums text-muted">
            {row.calls_10m} / 10 min · {row.calls_1m} / min
          </span>
        </div>
        <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-[color:var(--line)]">
          <div
            className={`h-full rounded-full ${toneBg(state.tone)}`}
            style={{ width: `${width}%`, opacity: state.tone === "good" ? 0.55 : 0.9 }}
          />
        </div>
        {row.budget_per_minute ? (
          <p className="mt-1 text-[10.5px] text-faint">
            Cupo público ~{Math.round(row.budget_per_minute)}/min
            {typeof row.utilization_pct === "number" ? ` · usando ${row.utilization_pct} %` : ""}
          </p>
        ) : null}
        {row.not_found > 0 ? (
          <p className="mt-0.5 text-[10.5px] text-faint">
            {row.not_found} 404 al probar endpoints de respaldo (no es un fallo)
          </p>
        ) : null}
        {(row.recovered ?? 0) > 0 ? (
          <p className="mt-0.5 text-[10.5px] text-faint">
            {row.recovered} 5xx que el siguiente intento resolvió
          </p>
        ) : null}
      </div>
      <div className="flex flex-col items-end gap-1">
        <span className={state.tone === "good" ? "badge badge--good" : `badge badge--${state.tone === "bad" ? "bad" : "warn"}`}>
          {state.label}
        </span>
        {row.avg_ms ? <span className="font-mono text-[10px] text-faint">{Math.round(row.avg_ms)} ms</span> : null}
      </div>
    </li>
  );
}

export function ApiUsagePanel() {
  const search = useSearchParams();
  const league = search.get("league");
  const [open, setOpen] = useState(false);
  const [usage, setUsage] = useState<ApiUsagePayload | null>(null);
  const [failed, setFailed] = useState<string | null>(null);
  const dialogRef = useRef<HTMLDialogElement>(null);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    if (open && !dialog.open) dialog.showModal();
    if (!open && dialog.open) dialog.close();
  }, [open]);

  const pull = useCallback(async () => {
    try {
      const payload = await getJson<ApiUsagePayload>(endpoint("/api/api-usage", league));
      setUsage(payload);
      setFailed(payload.ok === false ? payload.error?.message || "El medidor no respondió." : null);
    } catch (reason) {
      setFailed(reason instanceof Error ? reason.message : "El medidor no respondió.");
    }
  }, [league]);

  // Una lectura al montar y otra cada vez que se abre el diálogo. Es RAM, no
  // red: no gasta peticiones ni dispara scrapers. El «Recargar» sigue a mano.
  useEffect(() => {
    let cancelled = false;
    getJson<ApiUsagePayload>(endpoint("/api/api-usage", league))
      .then((payload) => {
        if (cancelled) return;
        setUsage(payload);
        setFailed(payload.ok === false ? payload.error?.message || "El medidor no respondió." : null);
      })
      .catch((reason: unknown) => {
        if (!cancelled) setFailed(reason instanceof Error ? reason.message : "El medidor no respondió.");
      });
    return () => {
      cancelled = true;
    };
  }, [open, league]);

  const risk = usage?.risk;
  const rate = usage?.rate;
  const tone = usageTone(usage);
  const verdict = usageVerdict(usage);
  const peak = maxSourceCalls(usage?.sources);
  const sources = usage?.sources || [];

  return (
    <>
      <button
        type="button"
        className="btn btn-secondary inline-flex"
        onClick={() => setOpen(true)}
        title="Llamadas que está haciendo el panel ahora mismo, por fuente"
        aria-haspopup="dialog"
      >
        <span className={`inline-flex items-center gap-1.5 font-semibold ${toneText(tone)}`}>
          <span className={`h-1.5 w-1.5 rounded-full ${toneBg(tone)}`} aria-hidden="true" />
          <span className="hidden sm:inline">Llamadas</span>
        </span>
        <span className="font-mono tabular-nums">{headlineChip(usage)}</span>
      </button>

      <dialog
        ref={dialogRef}
        className="bid-dialog data-health-dialog"
        onClose={() => setOpen(false)}
        onClick={(event) => {
          if (event.target === dialogRef.current) setOpen(false);
        }}
      >
        <div className="bid-dialog__body max-h-[min(88vh,760px)] overflow-y-auto">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div>
              <p className="eyebrow">Ritmo de llamadas</p>
              <h2 className="section-title mt-1">¿Cuántas peticiones estoy haciendo?</h2>
              <p className="section-support mt-1">
                Cuenta real de este proceso, por fuente. Los aciertos de caché no gastan petición y van aparte.
              </p>
            </div>
            <div className="flex flex-wrap items-center gap-2">
              <button
                type="button"
                className="btn btn-secondary !px-2.5 !py-1 text-xs"
                onClick={() => void pull()}
                title="Vuelve a leer los contadores. No sale a Internet."
              >
                Recargar
              </button>
              <CopyNetworkReportButton />
              <button type="button" className="btn btn-secondary !px-2.5 !py-1 text-xs" onClick={() => setOpen(false)}>
                Cerrar
              </button>
            </div>
          </div>

          {failed && !usage ? (
            <p className="mt-6 text-sm text-coral">{failed}</p>
          ) : !usage?.ok ? (
            <p className="mt-6 text-sm text-muted">Leyendo contadores…</p>
          ) : (
            <>
              <section className="mt-5 rounded-xl border border-[color:var(--line)] bg-[color:var(--surface-strong)] p-4">
                <div className="flex flex-wrap items-baseline gap-3">
                  <span className={verdict.badge}>{verdict.label}</span>
                  <span className="font-mono text-3xl font-semibold tracking-[-0.04em] text-ink">
                    {perMinute(rate?.per_minute)}
                  </span>
                  <span className="text-sm text-muted">
                    ahora mismo · banda {rateBandLabel(rate?.per_minute)}
                  </span>
                  <span className="ml-auto font-mono text-sm text-muted" title="100 = margen completo; baja con 429, reintentos y ráfagas">
                    Margen {risk?.score ?? "—"}%
                  </span>
                </div>
                <RateGauge perMinuteValue={rate?.per_minute ?? 0} />
                <p className="mt-3 text-sm font-medium leading-6 text-ink">{risk?.headline}</p>
                <p className="mt-1 text-xs leading-5 text-muted">{risk?.advice}</p>
                <ul className="mt-2 space-y-1">
                  {riskReasons(risk).map((line) => (
                    <li key={line} className="text-xs leading-5 text-muted">
                      · {line}
                    </li>
                  ))}
                </ul>
              </section>

              <section className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4">
                <Stat label="Último minuto" value={String(rate?.calls_1m ?? 0)} hint="llamadas reales" />
                <Stat label="Últimos 10 min" value={String(rate?.calls_10m ?? 0)} hint={perMinute(rate?.per_minute_10m)} />
                <Stat
                  label="Simultáneas"
                  value={String(usage.in_flight?.now ?? 0)}
                  hint={`pico 1 min: ${usage.in_flight?.peak_1m ?? 0}`}
                  tone={(usage.in_flight?.peak_1m ?? 0) >= 6 ? "text-gold" : "text-ink"}
                />
                <Stat
                  label="429 en 10 min"
                  value={String(usage.windows?.[1]?.rate_limited ?? 0)}
                  hint={`${usage.windows?.[1]?.retries ?? 0} reintentos`}
                  tone={(usage.windows?.[1]?.rate_limited ?? 0) > 0 ? "text-coral" : "text-ink"}
                />
              </section>

              <section className="mt-4 rounded-xl border border-[color:var(--line)] bg-[color:var(--surface)] p-3">
                <div className="flex flex-wrap items-baseline justify-between gap-2">
                  <h3 className="text-sm font-semibold text-ink">Estabilidad de la fuente</h3>
                  <span className={`text-[11px] font-semibold ${toneText(stabilityTone(usage.stability))}`}>
                    {usage.stability?.level === "warn" ? "Vigilar" : "Correcta"}
                  </span>
                </div>
                <p className="mt-1 text-xs leading-5 text-muted">{usage.stability?.headline}</p>
                {statusMixLabel(usage.stability?.status_mix) ? (
                  <p className="mt-1 font-mono text-[11px] text-faint">
                    {statusMixLabel(usage.stability?.status_mix)}
                  </p>
                ) : null}
                <p className="mt-1.5 text-[11px] leading-5 text-faint">{usage.stability?.note}</p>
              </section>

              <Timeline usage={usage} />

              <section className="mt-4">
                <div className="flex flex-wrap items-baseline justify-between gap-2">
                  <h3 className="text-sm font-semibold text-ink">Reparto por fuente</h3>
                  <span className="text-[11px] text-faint">
                    {usage.totals?.calls ?? 0} llamadas desde el arranque ({shortDuration(usage.uptime_seconds)})
                  </span>
                </div>
                {sources.length === 0 ? (
                  <p className="mt-2 text-sm leading-6 text-muted">
                    Aún no ha salido ninguna petición desde este arranque. Pulsa Actualizar y vuelve aquí: el
                    contador se llena con las llamadas reales.
                  </p>
                ) : (
                  <ul className="mt-2 divide-y divide-[color:var(--line)] overflow-hidden rounded-xl border border-[color:var(--line)]">
                    {sources.map((row) => (
                      <SourceRow key={row.id} row={row} peak={peak} />
                    ))}
                  </ul>
                )}
              </section>

              <section className="mt-4 rounded-xl border border-[color:var(--line)] bg-[color:var(--surface)] p-3">
                <h3 className="text-sm font-semibold text-ink">Cómo se lee este número</h3>
                <ul className="mt-1.5 space-y-1 text-[11.5px] leading-5 text-muted">
                  {(risk?.rules || []).map((line) => (
                    <li key={line}>· {line}</li>
                  ))}
                  {(usage.notes || []).map((line) => (
                    <li key={line}>· {line}</li>
                  ))}
                </ul>
                <p className="mt-2 text-[11px] leading-5 text-faint">{usage.scope}</p>
              </section>
            </>
          )}
        </div>
      </dialog>
    </>
  );
}

"use client";

import { useMemo, useState } from "react";
import { ErrorCard, Skeleton } from "@/components/Feedback";
import { PlayerAvatar } from "@/components/PlayerAvatar";
import { accel, eur, glass, jornadaEv, pct, playerName, points, projectedLineupPoints, titularShare } from "@/lib/format";
import type { Gap, OptimizePayload, Player, SquadsPayload } from "@/lib/types";

const ROW_Y: Record<string, number> = { DEL: 16, MC: 40, DEF: 66, POR: 88 };
const LINES = ["DEL", "MC", "DEF", "POR"] as const;
const LINE_LABEL: Record<string, string> = {
  DEL: "Delanteros",
  MC: "Medios",
  DEF: "Defensas",
  POR: "Portero",
};

type Token = Player & {
  gap?: boolean;
  label?: string;
  x: number;
  y: number;
};

function xFor(index: number, count: number): number {
  if (count <= 1) return 50;
  const margin = count >= 5 ? 12 : 18;
  return margin + (index * (100 - margin * 2)) / (count - 1);
}

export function layoutXi(players: Player[] | undefined, gaps: Gap[] | undefined): Token[] {
  const groups: Record<string, Array<Player & { gap?: boolean; label?: string }>> = {
    POR: [],
    DEF: [],
    MC: [],
    DEL: [],
  };
  for (const player of players || []) {
    if (player.position && groups[player.position]) groups[player.position].push(player);
  }
  for (const gap of gaps || []) {
    const count = Number(gap.missing) || 0;
    for (let index = 0; index < count; index += 1) {
      if (!gap.position || !groups[gap.position]) continue;
      groups[gap.position].push({
        gap: true,
        position: gap.position,
        label: `Falta 1 ${gap.position}`,
      });
    }
  }
  const placed: Token[] = [];
  for (const position of ["DEL", "MC", "DEF", "POR"]) {
    const line = groups[position].slice().sort((a, b) => {
      if (Boolean(a.gap) !== Boolean(b.gap)) return a.gap ? 1 : -1;
      return playerName(a).localeCompare(playerName(b), "es");
    });
    line.forEach((player, index) => {
      placed.push({ ...player, x: xFor(index, line.length), y: ROW_Y[position] });
    });
  }
  return placed;
}

function voidCopy(reasons: string[] | undefined): string {
  const labels: Record<string, string> = {
    empty_slot: "falta cerrar el once",
    negative_cash: "la caja es negativa",
  };
  const text = (reasons || []).map((reason) => labels[reason] || reason);
  return text.join(" · ") || "sin once completo";
}

function starterRing(value: number | null | undefined): string {
  const normalized = titularShare(value);
  const share = normalized !== null ? Math.max(0, Math.min(100, Math.round(normalized * 100))) : 0;
  return `conic-gradient(#f3e2b0 ${share}%, rgba(255,255,255,0.22) ${share}%)`;
}

function tokenKey(player: Token, index: number): string {
  return `${player.player_id || player.label || player.position}-${index}`;
}

function applySquadDelta(player: Player, deltas: Map<string, number>): Player {
  if (typeof player.price_delta === "number" || !player.player_id) return player;
  const delta = deltas.get(String(player.player_id));
  if (typeof delta !== "number") return player;
  return { ...player, price_delta: delta };
}

function priceMove(value: number | null | undefined): { text: string; tone: string } | null {
  if (typeof value !== "number") return null;
  return {
    text: `${accel(value)} €`,
    tone: value < 0 ? "text-coral" : value > 0 ? "text-mint" : "text-muted",
  };
}

function statusLabel(status: string | null | undefined): string | null {
  if (!status) return null;
  const folded = status.trim().toLowerCase();
  if (folded === "doubtful" || folded === "doubt" || folded === "duda") return "Duda";
  if (folded === "injured" || folded === "injury" || folded === "lesionado" || folded === "out" || folded === "baja") return "Lesión";
  if (folded === "suspended" || folded === "sanctioned" || folded === "sancionado") return "Sanción";
  return null;
}

function Silhouette() {
  return (
    <svg viewBox="0 0 24 24" className="h-4 w-4" aria-hidden="true">
      <circle cx="12" cy="8" r="3" fill="none" stroke="currentColor" strokeWidth="1.6" strokeDasharray="2.2 1.6" />
      <path
        d="M6.5 19.2c.8-2.8 2.8-4.2 5.5-4.2s4.7 1.4 5.5 4.2"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.6"
        strokeLinecap="round"
      />
    </svg>
  );
}

function TokenView({
  player,
  active,
  onSelect,
}: {
  player: Token;
  active: boolean;
  onSelect: () => void;
}) {
  if (player.gap) {
    const label = player.label || `Fichar ${player.position || ""}`.trim();
    return (
      <button
        type="button"
        className={active ? "token token-gap token--active" : "token token-gap"}
        data-token
        data-gap="true"
        data-position={player.position || ""}
        data-name={label}
        style={{ left: `${player.x}%`, top: `${player.y}%` }}
        title={label}
        aria-pressed={active}
        onClick={onSelect}
      >
        <div className="ring">
          <div className="avatar">
            <Silhouette />
          </div>
        </div>
        <div className="name">{label}</div>
        <div className="meta">hueco</div>
      </button>
    );
  }
  const name = playerName(player);
  const flag = statusLabel(player.player_status);
  const move = priceMove(player.price_delta);
  const estimated = player.p_titular_source === "week_points" ? " est." : "";
  const ev = jornadaEv(player);
  const ifStarts =
    typeof player.points_if_starts === "number"
      ? player.points_if_starts
      : typeof player.expected_points === "number" && typeof player.jornada_ev === "number"
        ? player.expected_points
        : null;
  const tooltipIfStarts =
    ifStarts !== null && ev !== null && Math.abs(ifStarts - ev) >= 0.35 ? ` · si titular ${points(ifStarts)}` : "";
  return (
    <button
      type="button"
      className={active ? "token token--active" : "token"}
      data-token
      data-position={player.position || ""}
      data-name={name}
      style={{ left: `${player.x}%`, top: `${player.y}%` }}
      title={`${name} · ${player.position || ""} · ${points(ev)} pts jornada · titular ${pct(player.p_titular)}${tooltipIfStarts}${estimated}`}
      aria-pressed={active}
      onClick={onSelect}
    >
      <div className="ring" style={{ background: starterRing(player.p_titular) }}>
        <PlayerAvatar player={player} />
      </div>
      <div className="name">{name}</div>
      <div className="meta">
        {points(ev)}
        {flag ? ` · ${flag}` : ""}
      </div>
      {move ? <div className={move.tone === "text-coral" ? "delta delta--down" : "delta delta--up"}>{move.text}</div> : null}
    </button>
  );
}

function Stat({ label, value, hint }: { label: string; value: string; hint?: string }) {
  return (
    <div className="rounded-xl border border-[color:var(--line)] bg-[color:var(--surface-strong)] px-3 py-2.5">
      <p className="metric-label">{label}</p>
      <p className="metric-value mt-1 text-lg text-ink">{value}</p>
      {hint ? <p className="mt-0.5 truncate text-[11px] text-muted">{hint}</p> : null}
    </div>
  );
}

function PlayerSheet({
  player,
  onClose,
}: {
  player: Token;
  onClose: () => void;
}) {
  if (player.gap) {
    return (
      <div className="rounded-2xl border border-[#f0cdc8] bg-[#fdf6f5] p-4">
        <div className="flex items-start justify-between gap-3">
          <div>
            <p className="eyebrow text-coral">Hueco</p>
            <h3 className="mt-1 text-lg font-semibold tracking-tight">{player.label || `Falta ${player.position}`}</h3>
            <p className="mt-1 text-sm text-muted">Esta plaza no tiene titular en la plantilla.</p>
          </div>
          <button type="button" className="btn btn-secondary !px-2.5 !py-1 text-xs" onClick={onClose}>
            Cerrar
          </button>
        </div>
      </div>
    );
  }
  const name = playerName(player);
  const flag = statusLabel(player.player_status);
  const normalized = titularShare(player.p_titular);
  const share = normalized !== null ? Math.max(0, Math.min(100, Math.round(normalized * 100))) : 0;
  const ev = jornadaEv(player);
  const ifStarts =
    typeof player.points_if_starts === "number"
      ? player.points_if_starts
      : typeof player.expected_points === "number" && typeof player.jornada_ev === "number"
        ? player.expected_points
        : null;
  return (
    <div className="rounded-2xl border border-[color:var(--line)] bg-[color:var(--surface-strong)] p-4">
      <div className="flex items-start gap-3">
        <div className="h-14 w-14 shrink-0 overflow-hidden rounded-2xl ring-1 ring-ink/10">
          <PlayerAvatar player={player} className="!h-14 !w-14 !rounded-2xl !text-sm" />
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0">
              <p className="eyebrow">{player.position || "Jugador"}</p>
              <h3 className="truncate text-lg font-semibold tracking-tight">{name}</h3>
              <p className="truncate text-sm text-muted">{player.club || "Club sin dato"}</p>
            </div>
            <button type="button" className="btn btn-secondary shrink-0 !px-2.5 !py-1 text-xs" onClick={onClose}>
              Cerrar
            </button>
          </div>
        </div>
      </div>
      <div className="mt-4 grid grid-cols-3 gap-3">
        <div>
          <p className="metric-label">Jornada</p>
          <p className="metric-value mt-1 text-2xl text-gold">{points(ev)}</p>
          {ifStarts !== null && ev !== null && Math.abs(ifStarts - ev) >= 0.35 ? (
            <p className="mt-0.5 text-[11px] text-muted">Si titular: {points(ifStarts)}</p>
          ) : null}
        </div>
        <div>
          <p className="metric-label">Titular</p>
          <p className="metric-value mt-1 text-2xl text-ink">{pct(player.p_titular)}</p>
        </div>
        <div>
          <p className="metric-label">Precio hoy</p>
          <p className={`metric-value mt-1 text-2xl ${priceMove(player.price_delta)?.tone || "text-muted"}`}>
            {priceMove(player.price_delta)?.text || "s/d"}
          </p>
        </div>
      </div>
      <div className="mt-3 h-1.5 overflow-hidden rounded-full bg-ink/10">
        <div className="h-full rounded-full bg-mint" style={{ width: `${share}%` }} />
      </div>
      <div className="mt-3 flex flex-wrap gap-2 text-[11px]">
        {flag ? <span className="badge badge--warn">{flag}</span> : <span className="badge badge--good">Disponible</span>}
        {player.p_titular_source === "week_points" ? <span className="badge badge--warn">Titularidad estimada</span> : null}
      </div>
    </div>
  );
}

export function Pitch({
  optimize,
  squads = null,
  loading = false,
}: {
  optimize: OptimizePayload | null;
  squads?: SquadsPayload | null;
  loading?: boolean;
}) {
  const [selected, setSelected] = useState<string | null>(null);
  const deltas = useMemo(() => {
    const map = new Map<string, number>();
    for (const player of squads?.self?.players || []) {
      if (player.player_id && typeof player.price_delta === "number") {
        map.set(String(player.player_id), player.price_delta);
      }
    }
    return map;
  }, [squads]);

  const xi = (optimize && optimize.ok !== false && Array.isArray(optimize.xi) ? optimize.xi : []).map((player) =>
    applySquadDelta(player, deltas),
  );
  const gaps = optimize && Array.isArray(optimize.gaps) ? optimize.gaps : [];
  const placed = useMemo(() => layoutXi(xi, gaps), [xi, gaps]);

  if (loading && !optimize) return <Skeleton title="Alineación" rows={8} />;
  if (!optimize || optimize.ok === false) {
    return <ErrorCard title="Alineación" payload={optimize || { error: { message: "Sin once calculado." } }} brief />;
  }

  const counts = optimize.partial ? optimize.eligible_counts || optimize.counts || {} : optimize.counts || {};
  const countLine = LINES.map((pos) => `${pos} ${counts[pos] ?? 0}`).join(" · ");
  const title = optimize.partial ? "Mejor once posible" : "Once óptimo";
  const bench = (Array.isArray(optimize.benched) ? optimize.benched : []).map((player) => applySquadDelta(player, deltas));
  const excluded = Array.isArray(optimize.excluded) ? optimize.excluded : [];
  const fills = Array.isArray(optimize.market_fills) ? optimize.market_fills : [];
  const saved = optimize.saved_lineup && optimize.saved_lineup.ok ? optimize.saved_lineup : null;
  const savedIds = new Set((saved?.xi || []).map((player) => String(player.player_id)));
  const recommendedIds = new Set(xi.filter((player) => player.player_id).map((player) => String(player.player_id)));
  const sameXi =
    Boolean(saved) && savedIds.size > 0 && savedIds.size === recommendedIds.size && [...savedIds].every((id) => recommendedIds.has(id));
  const enters = xi.filter((player) => player.player_id && !savedIds.has(String(player.player_id)));
  const leaves = (saved?.xi || []).filter((player) => player.player_id && !recommendedIds.has(String(player.player_id)));

  const real = placed.filter((player) => !player.gap);
  const starterValues = real.map((player) => titularShare(player.p_titular)).filter((value): value is number => value !== null);
  const starterAvg = starterValues.length ? starterValues.reduce((sum, value) => sum + value, 0) / starterValues.length : null;
  const doubts = real.filter((player) => statusLabel(player.player_status)).length;
  const gapCount = placed.filter((player) => player.gap).length;
  const lineupEv =
    projectedLineupPoints(xi) ?? (typeof optimize.expected_points === "number" ? optimize.expected_points : null);
  const maxPoints = real.reduce((max, player) => Math.max(max, jornadaEv(player) ?? 0), 0);
  const active = placed.find((player, index) => tokenKey(player, index) === selected) || null;

  const linePoints = (position: string) =>
    real.filter((player) => player.position === position).reduce((sum, player) => sum + (jornadaEv(player) ?? 0), 0);

  return (
    <article className={glass("p-4 md:p-5")}>
      <div className="flex flex-wrap items-end justify-between gap-3">
        <div>
          <p className="eyebrow">Alineación</p>
          <h2 className="section-title mt-1">
            {title}
            {optimize.formation ? (
              <span className="metric-value ml-2 align-middle text-[0.95em] text-gold">{optimize.formation}</span>
            ) : null}
          </h2>
          <p className="section-support">
            {optimize.manager_name || "Tu plantilla"} · {countLine}
          </p>
        </div>
      </div>

      <div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4">
        <Stat label="Proyección" value={points(lineupEv)} hint="valor esperado del once" />
        <Stat label="Titularidad" value={pct(starterAvg)} hint="media del once" />
        <Stat label="Alertas" value={String(doubts)} hint={doubts ? "duda, lesión o sanción" : "sin avisos"} />
        <Stat label="Huecos" value={String(gapCount)} hint={gapCount ? "plazas por cubrir" : "once cerrado"} />
      </div>

      {optimize.matchday_void ? (
        <p className="callout mt-4">
          Jornada a 0 · {voidCopy(optimize.void_reasons)}. El borde discontinuo marca el fichaje que falta.
        </p>
      ) : null}

      <div className="mt-5 grid items-start gap-5 lg:grid-cols-[minmax(280px,400px)_minmax(0,1fr)]">
        <div className="lg:sticky lg:top-24">
          <div className="flex justify-center">
            <div className="pitch">
              <svg viewBox="0 0 68 105" preserveAspectRatio="none" aria-hidden="true">
                <g fill="none" stroke="rgba(255,255,255,0.78)" strokeWidth="0.4">
                  <rect x="1.2" y="1.2" width="65.6" height="102.6" rx="0.6" />
                  <line x1="1.2" y1="52.5" x2="66.8" y2="52.5" />
                  <circle cx="34" cy="52.5" r="9.15" />
                  <circle cx="34" cy="52.5" r="0.55" fill="rgba(255,255,255,0.78)" stroke="none" />
                  <rect x="13.84" y="1.2" width="40.32" height="16.5" />
                  <rect x="24.84" y="1.2" width="18.32" height="5.5" />
                  <rect x="13.84" y="87.3" width="40.32" height="16.5" />
                  <rect x="24.84" y="98.3" width="18.32" height="5.5" />
                  <path d="M24.8 17.7a9.2 9.2 0 0 0 18.4 0" />
                  <path d="M24.8 87.3a9.2 9.2 0 0 1 18.4 0" />
                  <circle cx="34" cy="12" r="0.5" fill="rgba(255,255,255,0.78)" stroke="none" />
                  <circle cx="34" cy="93" r="0.5" fill="rgba(255,255,255,0.78)" stroke="none" />
                </g>
              </svg>
              <div className="pitch-xi">
                {placed.map((player, index) => {
                  const key = tokenKey(player, index);
                  return (
                    <TokenView
                      key={key}
                      player={player}
                      active={selected === key}
                      onSelect={() => setSelected((current) => (current === key ? null : key))}
                    />
                  );
                })}
              </div>
            </div>
          </div>
          <p className="mt-2 text-center text-[11px] text-faint">El aro dorado es la probabilidad de ser titular.</p>
        </div>

        <div className="min-w-0 space-y-4">
          {active ? <PlayerSheet player={active} onClose={() => setSelected(null)} /> : null}

          {LINES.map((position) => {
            const line = placed.filter((player) => player.position === position);
            if (!line.length) return null;
            return (
              <section key={position}>
                <div className="mb-1.5 flex items-baseline justify-between gap-3">
                  <p className="eyebrow">{LINE_LABEL[position]}</p>
                  <p className="metric-value text-xs text-gold">{points(linePoints(position))} pts</p>
                </div>
                <ul className="overflow-hidden rounded-xl border border-[color:var(--line)]">
                  {line.map((player) => {
                    const index = placed.indexOf(player);
                    const key = tokenKey(player, index);
                    const name = player.gap ? player.label || "Hueco" : playerName(player);
                    const width =
                      !player.gap && maxPoints > 0 && jornadaEv(player) !== null
                        ? Math.max(8, Math.round(((jornadaEv(player) ?? 0) / maxPoints) * 100))
                        : 0;
                    return (
                      <li key={key} className="border-b border-[color:var(--line)] last:border-b-0">
                        <button
                          type="button"
                          className={
                            selected === key
                              ? "flex w-full items-center gap-3 bg-[color:var(--gold-soft)] px-3 py-2.5 text-left"
                              : "flex w-full items-center gap-3 px-3 py-2.5 text-left transition-colors hover:bg-ink/[0.03]"
                          }
                          onClick={() => setSelected((current) => (current === key ? null : key))}
                        >
                          <span className="w-9 shrink-0">
                            {player.gap ? (
                              <span className="grid h-9 w-9 place-items-center rounded-full border border-dashed border-coral/50 text-coral">
                                <Silhouette />
                              </span>
                            ) : (
                              <PlayerAvatar player={player} size="sm" />
                            )}
                          </span>
                          <span className="min-w-0 flex-1">
                            <span className="block truncate text-sm font-medium">{name}</span>
                            <span className="mt-1 block h-1 overflow-hidden rounded-full bg-ink/10">
                              <span className="block h-full rounded-full bg-mint/80" style={{ width: `${width}%` }} />
                            </span>
                          </span>
                          <span className="shrink-0 text-right">
                            <span className="metric-value block text-sm text-gold">
                              {player.gap ? "—" : points(jornadaEv(player))}
                            </span>
                            <span className="block text-[11px] text-muted">{player.gap ? "hueco" : pct(player.p_titular)}</span>
                            {!player.gap && priceMove(player.price_delta) ? (
                              <span className={`metric-value block text-[11px] ${priceMove(player.price_delta)!.tone}`}>
                                {priceMove(player.price_delta)!.text}
                              </span>
                            ) : null}
                          </span>
                        </button>
                      </li>
                    );
                  })}
                </ul>
              </section>
            );
          })}

          {fills.length ? (
            <div className="space-y-3">
              <p className="eyebrow">Qué fichar para cerrar el once</p>
              {fills.map((gap, index) => {
                const options = Array.isArray(gap.options) ? gap.options : [];
                return (
                  <div key={`${gap.position}-${index}`} className="callout">
                    <p className="text-sm font-medium">{gap.label || `Falta ${gap.missing} ${gap.position}`}</p>
                    <ul className="mt-1">
                      {options.length ? (
                        options.map((option) => (
                          <li key={String(option.player_id)} className="flex items-center justify-between gap-3 py-1.5 text-sm">
                            <span className="truncate">
                              {playerName(option)}
                              {option.club ? <span className="text-muted"> · {option.club}</span> : null}
                            </span>
                            <span className="metric-value shrink-0 text-xs">{eur(option.sale_price)}</span>
                          </li>
                        ))
                      ) : (
                        <li className="py-1 text-sm opacity-80">Nadie de esa posición tiene precio en el mercado.</li>
                      )}
                    </ul>
                  </div>
                );
              })}
            </div>
          ) : null}

          {saved ? (
            <div className="rounded-2xl border border-[color:var(--line)] p-4">
              <div className="flex flex-wrap items-center justify-between gap-2">
                <p className="eyebrow">Alineación de la app</p>
                <span className={sameXi ? "badge badge--good" : "badge badge--warn"}>
                  {sameXi ? "Coincide" : "Distinta"}
                </span>
              </div>
              <p className="mt-2 text-sm text-ink">
                <span className="metric-value text-gold">{saved.formation || "sin formación"}</span>
              </p>
              {!sameXi && (enters.length || leaves.length) ? (
                <div className="mt-3 grid gap-3 sm:grid-cols-2">
                  <div>
                    <p className="text-[11px] font-semibold uppercase tracking-[0.08em] text-mint">Entran</p>
                    <p className="mt-1 text-sm leading-6">{enters.length ? enters.map((player) => playerName(player)).join(", ") : "—"}</p>
                  </div>
                  <div>
                    <p className="text-[11px] font-semibold uppercase tracking-[0.08em] text-coral">Salen</p>
                    <p className="mt-1 text-sm leading-6">{leaves.length ? leaves.map((player) => playerName(player)).join(", ") : "—"}</p>
                  </div>
                </div>
              ) : null}
            </div>
          ) : (
            <p className="text-xs text-faint">La API no devolvió la alineación guardada en la app.</p>
          )}

          {bench.length ? (
            <div>
              <p className="eyebrow mb-2">Banquillo</p>
              <ul className="grid gap-2 sm:grid-cols-2">
                {bench.map((player) => (
                  <li
                    key={String(player.player_id)}
                    className="flex items-center gap-2.5 rounded-xl border border-[color:var(--line)] px-2.5 py-2"
                  >
                    <PlayerAvatar player={player} size="sm" />
                    <span className="min-w-0 flex-1">
                      <span className="block truncate text-sm font-medium">{playerName(player)}</span>
                      <span className="text-[11px] text-muted">{player.position || ""}</span>
                    </span>
                    <span className="text-right">
                      <span className="metric-value block text-xs text-gold">{points(jornadaEv(player))}</span>
                      {priceMove(player.price_delta) ? (
                        <span className={`metric-value block text-[11px] ${priceMove(player.price_delta)!.tone}`}>
                          {priceMove(player.price_delta)!.text}
                        </span>
                      ) : null}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          ) : null}

          {excluded.length ? (
            <p className="text-xs leading-5 text-muted">
              Fuera del once:{" "}
              {excluded
                .slice(0, 8)
                .map((player) => `${playerName(player)} (${player.excluded_reason || "fuera"})`)
                .join(" · ")}
            </p>
          ) : null}

          {optimize.calibration_note ? (
            <details className="text-xs text-muted">
              <summary className="cursor-pointer text-muted-strong transition-colors hover:text-ink">
                Cómo se calculan los puntos
              </summary>
              <p className="mt-2 leading-5">{optimize.calibration_note}</p>
            </details>
          ) : null}
        </div>
      </div>
    </article>
  );
}

"use client";

import { useState } from "react";
import { initials, playerName } from "@/lib/format";
import type { Player } from "@/lib/types";

export function PlayerAvatar({
  player,
  className = "",
  size = "md",
}: {
  player: Player | null | undefined;
  className?: string;
  size?: "sm" | "md";
}) {
  const [failedSrc, setFailedSrc] = useState<string | null>(null);
  const name = playerName(player);
  const src = player?.image_url || null;
  const box =
    size === "sm"
      ? "h-8 w-8 shrink-0 text-[10px] ring-1 ring-ink/10"
      : "h-full w-full text-[11px]";

  // Se recuerda qué URL falló, no un booleano: al cambiar de jugador la foto
  // nueva se intenta sola, sin sembrar estado desde un efecto.
  const failed = src !== null && failedSrc === src;

  if (src && !failed) {
    return (
      <img
        src={src}
        alt=""
        className={`avatar object-cover ${box} ${className}`.trim()}
        loading="lazy"
        referrerPolicy="no-referrer"
        onError={() => setFailedSrc(src)}
      />
    );
  }

  return <div className={`avatar ${box} ${className}`.trim()}>{initials(name)}</div>;
}

"use client";

import { useEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { ErrorCard, Skeleton } from "@/components/Feedback";
import { PlayerAvatar } from "@/components/PlayerAvatar";
import {
  cashClass,
  clockLabel,
  deltaEur,
  deltaTone,
  eur,
  glass,
  initials,
  multiple,
  playerName,
  points,
  pct,
  roiPct,
  stamp,
} from "@/lib/format";
import { enrichSquadsPayload } from "@/lib/squadEnrich";
import { squadHoldings, squadPatrimonio, squadTotals } from "@/lib/squadTotals";
import type {
  ActivityEvent,
  ClauseIntelOffer,
  ClauseIntelPayload,
  ClauseRow,
  NeedRival,
  NeedsPayload,
  RivalPlayer,
  RivalSquad,
  SquadsPayload,
  TrendsPayload,
} from "@/lib/types";

type RivalSort = "rank" | "patrimonio" | "cash" | "value" | "delta";
type SheetTab = "plantilla" | "mercado" | "clausulas";

function needsByTeam(needs: NeedsPayload | null): Map<string, NeedRival> {
  const map = new Map<string, NeedRival>();
  for (const rival of needs?.ok ? needs.rivals || [] : []) map.set(String(rival.team_id), rival);
  return map;
}

function rivalLabel(squad: RivalSquad): string {
  return squad.manager_name || squad.fantasy_team_name || String(squad.team_id || "Rival");
}

function ruleLabel(row: ClauseRow): string {
  if (row.clause_rule === "A") return "Regla A";
  if (row.clause_rule === "B") return "Regla B";
  return "Fuera";
}

function ruleTone(row: ClauseRow): string {
  if (row.clause_rule === "A") return "text-mint";
  if (row.clause_rule === "B") return "text-gold";
  return "text-muted";
}

function ledgerFromNeeds(needs: NeedsPayload | null, teamId: string): NeedRival["ledger"] | null {
  return (needs?.ok ? needs.rivals || [] : []).find((row) => String(row.team_id) === teamId)?.ledger ?? null;
}

function sortKey(squad: RivalSquad, mode: RivalSort): number {
  if (mode === "cash") return typeof squad.cash_eur === "number" ? squad.cash_eur : Number.NEGATIVE_INFINITY;
  if (mode === "value") {
    const value = squadTotals(squad).market_value_total;
    return typeof value === "number" ? value : Number.NEGATIVE_INFINITY;
  }
  if (mode === "delta") {
    const delta = squadTotals(squad).price_delta_day;
    return typeof delta === "number" ? delta : Number.NEGATIVE_INFINITY;
  }
  if (mode === "patrimonio") {
    const patrimonio = squadPatrimonio(squad);
    return typeof patrimonio === "number" ? patrimonio : Number.NEGATIVE_INFINITY;
  }
  return Number.NEGATIVE_INFINITY;
}

function sortSquads(list: RivalSquad[], mode: RivalSort): RivalSquad[] {
  return list.slice().sort((a, b) => {
    if (mode === "rank") {
      const left = typeof a.rank === "number" ? a.rank : 9999;
      const right = typeof b.rank === "number" ? b.rank : 9999;
      if (left !== right) return left - right;
      return rivalLabel(a).localeCompare(rivalLabel(b), "es");
    }
    const delta = sortKey(b, mode) - sortKey(a, mode);
    if (delta) return delta;
    return rivalLabel(a).localeCompare(rivalLabel(b), "es");
  });
}

function windowLabel(intel: ClauseIntelPayload | null): string {
  if (!intel || intel.ok === false) return "Sin lectura";
  if (intel.clause_window_open === true) {
    const close = intel.clause_market_close;
    if (close?.local_date && close?.local_time) return `Abierta · cierra ${close.local_date} ${close.local_time}`;
    return "Abierta";
  }
  if (intel.clause_window_open === false) return "Cerrada";
  return "Ventana s/d";
}

const POS_ORDER = ["POR", "DEF", "MC", "MED", "DEL"];
const POS_LABEL: Record<string, string> = {
  POR: "Portería",
  DEF: "Defensa",
  MC: "Mediocampo",
  MED: "Mediocampo",
  DEL: "Delantera",
};

function positionGroups(players: RivalPlayer[]) {
  const buckets = new Map<string, RivalPlayer[]>();
  for (const player of players) {
    const pos = String(player.position || "?").toUpperCase();
    buckets.set(pos, [...(buckets.get(pos) || []), player]);
  }
  const ordered = POS_ORDER.filter((pos) => buckets.has(pos)).map((pos) => ({
    position: pos,
    label: POS_LABEL[pos] || pos,
    rows: buckets.get(pos) || [],
  }));
  for (const [pos, rows] of buckets) {
    if (!POS_ORDER.includes(pos)) ordered.push({ position: pos, label: POS_LABEL[pos] || pos, rows });
  }
  return ordered;
}

function acquisitionLabel(kind: string | null | undefined): string {
  if (kind === "clausula") return "Cláusula";
  if (kind === "mercado") return "Mercado";
  return "Sin origen";
}

function rankTone(rank: number | null | undefined, isSelf: boolean): string {
  if (isSelf) return "rival-rank rival-rank--self";
  if (rank === 1) return "rival-rank rival-rank--gold";
  if (rank === 2) return "rival-rank rival-rank--silver";
  if (rank === 3) return "rival-rank rival-rank--bronze";
  return "rival-rank";
}

function eventTone(event: ActivityEvent): string {
  if (event.kind === "sell" || (typeof event.signed_eur === "number" && event.signed_eur > 0)) return "text-mint";
  if (event.kind === "buy" || event.kind === "clause") return "text-coral";
  return "text-muted-strong";
}

function Metric({ label, value, tone, hint }: { label: string; value: string; tone?: string; hint?: string }) {
  return (
    <div>
      <p className="metric-label">{label}</p>
      <p className={`metric-value mt-1 text-lg ${tone || "text-ink"}`}>{value}</p>
      {hint ? <p className="mt-0.5 text-[11px] text-faint">{hint}</p> : null}
    </div>
  );
}

function listMetric(squad: RivalSquad, sort: RivalSort): { label: string; value: string; tone?: string } {
  const totals = squadTotals(squad);
  if (sort === "delta") {
    return { label: "Δ hoy", value: deltaEur(totals.price_delta_day), tone: deltaTone(totals.price_delta_day) };
  }
  if (sort === "cash") {
    return { label: "Caja", value: eur(squad.cash_eur), tone: cashClass(squad.cash_eur) };
  }
  if (sort === "patrimonio") {
    return { label: "Patrimonio", value: eur(squadPatrimonio(squad)), tone: "text-gold" };
  }
  if (sort === "value") {
    return { label: "Valor", value: eur(totals.market_value_total), tone: "text-ink" };
  }
  const holdings = squadHoldings(squad);
  if (typeof holdings.gain_eur === "number") {
    return { label: "Plusvalía", value: deltaEur(holdings.gain_eur), tone: deltaTone(holdings.gain_eur) };
  }
  return { label: "Δ hoy", value: deltaEur(totals.price_delta_day), tone: deltaTone(totals.price_delta_day) };
}

function RivalCard({
  squad,
  isSelf,
  sort,
  onOpen,
}: {
  squad: RivalSquad;
  isSelf: boolean;
  sort: RivalSort;
  onOpen: () => void;
}) {
  const name = rivalLabel(squad);
  const teamName = squad.fantasy_team_name && squad.fantasy_team_name !== name ? squad.fantasy_team_name : null;
  const metric = listMetric(squad, sort);
  return (
    <button type="button" onClick={onOpen} className={`rival-card group w-full px-4 py-3.5 text-left ${isSelf ? "rival-card--self" : ""}`}>
      <div className="flex items-center gap-3">
        <div className={rankTone(squad.rank, isSelf)}>
          {typeof squad.rank === "number" ? squad.rank : initials(name).slice(0, 2)}
        </div>
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span className="truncate text-[15px] font-semibold tracking-tight text-ink">{name}</span>
            {isSelf ? <span className="badge badge--good text-[10px]">Tú</span> : null}
          </div>
          <p className="mt-0.5 truncate text-[12px] text-muted">
            {teamName ? `${teamName} · ` : ""}
            caja <span className={cashClass(squad.cash_eur)}>{eur(squad.cash_eur)}</span>
          </p>
        </div>
        <div className="shrink-0 text-right">
          <p className={`metric-value text-sm ${metric.tone || "text-ink"}`}>{metric.value}</p>
          <p className="text-[10px] text-faint">{metric.label}</p>
        </div>
      </div>
    </button>
  );
}

function PlayerDeal({
  player,
  events,
  open,
  onToggle,
}: {
  player: RivalPlayer;
  events: ActivityEvent[];
  open: boolean;
  onToggle: () => void;
}) {
  const related = events.filter((event) => event.player_id && String(event.player_id) === String(player.player_id));
  return (
    <div className={`rival-player-wrap ${open ? "rival-player-wrap--open" : ""}`}>
      <button type="button" onClick={onToggle} className="rival-player w-full text-left">
        <PlayerAvatar player={player} size="sm" />
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-semibold tracking-tight text-ink">{playerName(player)}</p>
          <p className="mt-0.5 flex flex-wrap items-center gap-1.5 text-[10px] text-faint">
            <span className="rival-pos">{player.position || "?"}</span>
            {player.club ? <span>{player.club}</span> : null}
            {player.acquisition_kind ? <span>{acquisitionLabel(player.acquisition_kind)}</span> : null}
          </p>
        </div>
        <div className="shrink-0 text-right">
          <p className={`metric-value text-xs ${deltaTone(player.gain_eur)}`}>{deltaEur(player.gain_eur)}</p>
          <p className="text-[10px] text-faint">{typeof player.roi === "number" ? roiPct(player.roi) : "sin coste"}</p>
        </div>
      </button>
      {open ? (
        <div className="rival-deal">
          <div className="grid grid-cols-2 gap-x-4 gap-y-3 sm:grid-cols-4">
            <Metric label="Pagó" value={eur(player.cost_eur)} hint={acquisitionLabel(player.acquisition_kind)} />
            <Metric label="Vale hoy" value={eur(player.market_value)} />
            <Metric label="Plusvalía" value={deltaEur(player.gain_eur)} tone={deltaTone(player.gain_eur)} />
            <Metric label="ROI" value={roiPct(player.roi)} tone={deltaTone(player.gain_eur)} />
          </div>
          <div className="mt-3 flex flex-wrap gap-x-4 gap-y-1 text-[11px] text-muted">
            <span>Cláusula {eur(player.buyout_clause)}</span>
            <span>{clockLabel(player.clause_lock)}</span>
            {player.acquired_at ? <span>Fichado {stamp(player.acquired_at)}</span> : null}
            {typeof player.p_titular === "number" ? <span>Titular {pct(player.p_titular)}</span> : null}
            {typeof player.own_expected_points === "number" ? <span>{points(player.own_expected_points)} pts</span> : null}
          </div>
          {typeof player.cost_eur !== "number" ? (
            <p className="mt-3 text-[12px] leading-5 text-muted">
              No hay compra ni cláusula en el historial. No se puede calcular rentabilidad de este fichaje.
            </p>
          ) : null}
          {related.length ? (
            <ul className="mt-3 space-y-1.5 border-t border-[color:var(--line)] pt-3">
              {related.map((event, index) => (
                <li key={`${event.at}-${index}`} className="flex items-center justify-between gap-3 text-[12px]">
                  <span className="text-muted-strong">
                    {event.label}
                    <span className="text-faint"> · {stamp(event.at) || "sin fecha"}</span>
                  </span>
                  <span className={`metric-value ${eventTone(event)}`}>{eur(event.amount_eur)}</span>
                </li>
              ))}
            </ul>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}

function MarketTab({
  squad,
  ledger,
}: {
  squad: RivalSquad;
  ledger?: NeedRival["ledger"] | null;
}) {
  const profile = squad.activity_profile;
  const holdings = squadHoldings(squad);
  const spent = (profile?.purchases_eur ?? ledger?.purchases_eur ?? 0) + (profile?.clauses_eur ?? ledger?.clauses_eur ?? 0);
  const sales = profile?.sales_eur ?? ledger?.sales_eur;
  const events = profile?.recent_events || [];
  const priced = (squad.players || [])
    .filter((player) => typeof player.gain_eur === "number")
    .slice()
    .sort((a, b) => (b.gain_eur ?? 0) - (a.gain_eur ?? 0));
  const winners = priced.filter((player) => (player.gain_eur ?? 0) > 0).slice(0, 3);
  const losers = priced
    .filter((player) => (player.gain_eur ?? 0) < 0)
    .slice()
    .sort((a, b) => (a.gain_eur ?? 0) - (b.gain_eur ?? 0))
    .slice(0, 3);
  const sold = events.filter((event) => event.kind === "sell");

  return (
    <section className="space-y-6">
      <div className="grid grid-cols-2 gap-4">
        <Metric label="Ha cobrado" value={eur(sales)} hint="Ventas en el historial" tone="text-mint" />
        <Metric
          label="Plusvalía vendida"
          value={deltaEur(profile?.realized_gain_eur)}
          tone={deltaTone(profile?.realized_gain_eur)}
          hint={
            typeof profile?.priced_sales === "number" && profile.priced_sales > 0
              ? `${profile.priced_sales} venta(s) con coste conocido`
              : "Sin ventas con coste"
          }
        />
        <Metric label="Ha gastado" value={eur(spent || null)} hint="Compras + cláusulas" />
        <Metric
          label="Plantilla ahora"
          value={deltaEur(holdings.gain_eur)}
          tone={deltaTone(holdings.gain_eur)}
          hint={typeof holdings.priced_count === "number" ? `${holdings.priced_count} con coste · ${roiPct(holdings.roi)}` : undefined}
        />
      </div>
      {ledger?.cash_is_ceiling ? (
        <p className="text-[12px] leading-5 text-faint">
          La caja reconstruida es un techo: algunas subidas de cláusula no aparecen en el historial.
        </p>
      ) : null}

      {winners.length || losers.length ? (
        <div className="grid gap-5 sm:grid-cols-2">
          <DealList title="Mejores fichajes" rows={winners} />
          <DealList title="Peores fichajes" rows={losers} />
        </div>
      ) : (
        <p className="text-sm text-muted">Sin costes rastreados en esta plantilla. Actualiza para sincronizar el historial.</p>
      )}

      {sold.length ? (
        <div>
          <p className="eyebrow">Dinero sacado</p>
          <ul className="mt-2 space-y-2">
            {sold.map((event, index) => (
              <li key={`${event.at}-${index}`} className="flex items-center justify-between gap-3 text-sm">
                <span className="min-w-0 truncate text-ink">{event.player_name || "Venta"}</span>
                <span className="metric-value text-mint">{eur(event.amount_eur)}</span>
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      {events.length ? (
        <div>
          <p className="eyebrow">Últimos movimientos</p>
          <ul className="mt-2 divide-y divide-[color:var(--line)]">
            {events.map((event, index) => (
              <li key={`${event.at}-${event.kind}-${index}`} className="flex items-start justify-between gap-3 py-2.5">
                <div className="min-w-0">
                  <p className="text-sm text-ink">
                    {event.label}
                    {event.player_name ? <span className="text-muted"> · {event.player_name}</span> : null}
                  </p>
                  <p className="text-[10px] text-faint">{stamp(event.at) || "Sin fecha"}</p>
                </div>
                <span className={`metric-value text-sm ${eventTone(event)}`}>{eur(event.amount_eur)}</span>
              </li>
            ))}
          </ul>
        </div>
      ) : (
        <p className="text-sm text-muted">Sin historial de operaciones para este manager.</p>
      )}
    </section>
  );
}

function DealList({ title, rows }: { title: string; rows: RivalPlayer[] }) {
  return (
    <div>
      <p className="eyebrow">{title}</p>
      {rows.length ? (
        <ul className="mt-2 space-y-2">
          {rows.map((player) => (
            <li key={String(player.player_id)} className="flex items-center gap-2">
              <PlayerAvatar player={player} size="sm" />
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-ink">{playerName(player)}</p>
                <p className="text-[10px] text-faint">
                  {eur(player.cost_eur)} → {eur(player.market_value)}
                </p>
              </div>
              <div className="text-right">
                <p className={`metric-value text-xs ${deltaTone(player.gain_eur)}`}>{deltaEur(player.gain_eur)}</p>
                <p className="text-[10px] text-faint">{roiPct(player.roi)}</p>
              </div>
            </li>
          ))}
        </ul>
      ) : (
        <p className="mt-2 text-xs text-muted">Nadie en esta lista.</p>
      )}
    </div>
  );
}

function RivalSheet({
  squad,
  isSelf,
  needs,
  clauses,
  clauseOffers,
  onClose,
}: {
  squad: RivalSquad | null;
  isSelf: boolean;
  needs: NeedsPayload | null;
  clauses: ClauseRow[];
  clauseOffers: ClauseIntelOffer[];
  onClose: () => void;
}) {
  const ref = useRef<HTMLDialogElement>(null);
  const [tab, setTab] = useState<SheetTab>("plantilla");
  const [openPlayer, setOpenPlayer] = useState<string | null>(null);
  const teamId = squad?.team_id != null ? String(squad.team_id) : null;

  // Al cambiar de rival, la ficha vuelve a la pestaña de plantilla. Se ajusta
  // durante el render (patrón de React) en vez de sembrarlo desde un efecto.
  const [shownTeamId, setShownTeamId] = useState(teamId);
  if (shownTeamId !== teamId) {
    setShownTeamId(teamId);
    setTab("plantilla");
    setOpenPlayer(null);
  }

  useEffect(() => {
    const dialog = ref.current;
    if (!dialog) return;
    if (squad && !dialog.open) dialog.showModal();
    if (!squad && dialog.open) dialog.close();
  }, [squad]);

  if (!squad || !teamId) {
    return (
      <dialog ref={ref} className="bid-dialog rival-dialog" onClose={onClose}>
        <div className="bid-dialog__body" />
      </dialog>
    );
  }

  const holdings = squadHoldings(squad);
  const players = squad.players || [];
  const groups = positionGroups(players);
  const events = squad.activity_profile?.recent_events || [];
  const teamClauses = clauses.filter((row) => String(row.team_id) === teamId);
  const tabs: { id: SheetTab; label: string }[] = [
    { id: "plantilla", label: "Plantilla" },
    { id: "mercado", label: "Mercado" },
    { id: "clausulas", label: "Cláusulas" },
  ];

  return (
    <dialog
      ref={ref}
      className="bid-dialog rival-dialog"
      onClose={onClose}
      onClick={(event) => {
        if (event.target === ref.current) onClose();
      }}
    >
      <div className="bid-dialog__body scroll-thin">
        <div className="rival-sheet-head">
          <div className="flex items-start justify-between gap-3">
            <div className="flex min-w-0 items-center gap-3">
              <div className={`${rankTone(squad.rank, isSelf)} !h-12 !w-12 !text-base`}>
                {typeof squad.rank === "number" ? squad.rank : initials(rivalLabel(squad))}
              </div>
              <div className="min-w-0">
                <p className="eyebrow">{isSelf ? "Tu equipo" : "Rival"}</p>
                <h3 className="truncate text-xl font-semibold tracking-tight text-ink">{rivalLabel(squad)}</h3>
              </div>
            </div>
            <button type="button" className="btn btn-secondary shrink-0" onClick={onClose}>
              Cerrar
            </button>
          </div>

          <div className="mt-4 grid grid-cols-3 gap-3 border-t border-[color:var(--line)] pt-4">
            <Metric label="Caja" value={eur(squad.cash_eur)} tone={cashClass(squad.cash_eur)} />
            <Metric label="Cobrado" value={eur(squad.activity_profile?.sales_eur)} tone="text-mint" />
            <Metric label="Plusvalía" value={deltaEur(holdings.gain_eur)} tone={deltaTone(holdings.gain_eur)} />
          </div>

          <div className="seg mt-4 w-full">
            {tabs.map((item) => (
              <button
                key={item.id}
                type="button"
                className={tab === item.id ? "seg__btn seg__btn--active" : "seg__btn"}
                onClick={() => setTab(item.id)}
              >
                {item.label}
              </button>
            ))}
          </div>
        </div>

        {tab === "plantilla" ? (
          <section className="mt-5 space-y-5">
            <p className="text-[12px] text-muted">Pulsa un jugador para ver qué pagó, cuánto vale y su ROI.</p>
            {groups.length ? (
              groups.map((group) => (
                <div key={group.position}>
                  <p className="mb-2 text-[11px] font-semibold uppercase tracking-wider text-faint">
                    {group.label}
                    <span className="ml-2 font-mono font-normal">{group.rows.length}</span>
                  </p>
                  <div className="space-y-2">
                    {group.rows.map((player) => {
                      const id = String(player.player_id);
                      return (
                        <PlayerDeal
                          key={id}
                          player={player}
                          events={events}
                          open={openPlayer === id}
                          onToggle={() => setOpenPlayer(openPlayer === id ? null : id)}
                        />
                      );
                    })}
                  </div>
                </div>
              ))
            ) : (
              <p className="text-sm text-muted">Esta plantilla no trae jugadores.</p>
            )}
          </section>
        ) : null}

        {tab === "mercado" ? (
          <section className="mt-5">
            <MarketTab squad={squad} ledger={ledgerFromNeeds(needs, teamId)} />
          </section>
        ) : null}

        {tab === "clausulas" ? (
          <section className="mt-5 space-y-4">
            {clauseOffers.map((row) => (
              <div key={String(row.player_id)} className="flex items-center gap-3">
                <PlayerAvatar player={row} size="sm" />
                <div className="min-w-0 flex-1">
                  <p className="font-medium text-ink">{playerName(row)}</p>
                  <p className="text-[11px] text-muted">
                    {eur(row.buyout_clause_eur)}
                    {typeof row.points_delta === "number" ? ` · +${points(row.points_delta)} pts` : ""}
                  </p>
                </div>
                <span className={row.decision === "PAGAR" ? "badge badge--good" : "badge badge--warn"}>
                  {row.decision === "PAGAR" ? "Pagar" : "Alternativa"}
                </span>
              </div>
            ))}
            {teamClauses.map((row) => (
              <div key={`${row.team_id}-${row.player_id}`}>
                <div className="flex items-center justify-between gap-2">
                  <p className="font-medium text-ink">{playerName(row)}</p>
                  <span className={`text-xs font-medium ${ruleTone(row)}`}>{ruleLabel(row)}</span>
                </div>
                <p className="mt-1 text-[11px] text-muted">
                  {eur(row.buyout_clause_eur)} · {multiple(row.clause_multiple)} · {clockLabel(row.clause_lock)}
                </p>
              </div>
            ))}
            {!clauseOffers.length && !teamClauses.length ? (
              <p className="text-sm text-muted">Ninguna cláusula destacada en esta lectura.</p>
            ) : null}
          </section>
        ) : null}
      </div>
    </dialog>
  );
}

function ExtraBlock({
  title,
  count,
  open,
  onToggle,
  children,
}: {
  title: string;
  count: number;
  open: boolean;
  onToggle: () => void;
  children: ReactNode;
}) {
  return (
    <div className="border-t border-[color:var(--line)]">
      <button type="button" className="flex w-full items-center justify-between gap-3 py-3.5 text-left" onClick={onToggle}>
        <span className="text-sm font-semibold text-ink">{title}</span>
        <span className="text-[12px] text-muted">
          {count} · {open ? "Ocultar" : "Ver"}
        </span>
      </button>
      {open ? <div className="pb-4">{children}</div> : null}
    </div>
  );
}

export function RivalsDashboard({
  squads,
  needs,
  trends = null,
  clauseIntel = null,
  clauseIntelLoading = false,
  loading = false,
}: {
  squads: SquadsPayload | null;
  needs: NeedsPayload | null;
  trends?: TrendsPayload | null;
  clauseIntel?: ClauseIntelPayload | null;
  clauseIntelLoading?: boolean;
  loading?: boolean;
}) {
  const [selectedTeam, setSelectedTeam] = useState<string | null>(null);
  const [rivalSort, setRivalSort] = useState<RivalSort>("rank");
  const [showOffers, setShowOffers] = useState(false);
  const [showClauses, setShowClauses] = useState(false);
  const view = useMemo(() => enrichSquadsPayload(squads, trends), [squads, trends]);
  const rivals = view?.rivals || [];
  const own = view?.self;
  const ownTeamId = own?.team_id != null ? String(own.team_id) : null;
  const leagueSquads = useMemo(() => {
    const all = [...rivals];
    if (own) all.push(own);
    return all;
  }, [rivals, own]);
  const sortedSquads = useMemo(() => sortSquads(leagueSquads, rivalSort), [leagueSquads, rivalSort]);
  const selectedSquad = useMemo(
    () => (selectedTeam ? leagueSquads.find((row) => String(row.team_id) === selectedTeam) || null : null),
    [selectedTeam, leagueSquads],
  );

  if (loading && !squads) return <Skeleton title="Rivales" rows={6} />;
  if (!view || view.ok === false) {
    return <ErrorCard title="Rivales" payload={view || squads || { error: { message: "Sin plantillas." } }} brief />;
  }

  const clauses = view.clauses || [];
  const offers = clauseIntel?.ok !== false ? clauseIntel?.offers || [] : [];
  const selectedOffers = selectedTeam ? offers.filter((row) => String(row.team_id) === selectedTeam) : [];

  return (
    <article className={glass("p-4 md:p-6")}>
      <header className="mb-5 flex flex-wrap items-end justify-between gap-4">
        <div>
          <p className="eyebrow">Liga</p>
          <h2 className="section-title mt-1">{leagueSquads.length} managers</h2>
          <p className="section-support">Lista corta. Entra en un rival para ver plantilla y su mercado.</p>
        </div>
        <div className="seg flex-wrap justify-end">
          {(
            [
              ["rank", "Puesto"],
              ["patrimonio", "Patrimonio"],
              ["cash", "Caja"],
              ["delta", "Δ hoy"],
            ] as const
          ).map(([key, label]) => (
            <button
              key={key}
              type="button"
              onClick={() => setRivalSort(key)}
              className={rivalSort === key ? "seg__btn seg__btn--active" : "seg__btn"}
            >
              {label}
            </button>
          ))}
        </div>
      </header>

      <div className="divide-y divide-[color:var(--line)] rounded-2xl border border-[color:var(--line)] bg-[color:var(--surface)]">
        {sortedSquads.length ? (
          sortedSquads.map((squad) => {
            const teamId = String(squad.team_id);
            return (
              <RivalCard
                key={teamId}
                squad={squad}
                sort={rivalSort}
                isSelf={ownTeamId !== null && teamId === ownTeamId}
                onOpen={() => setSelectedTeam(teamId)}
              />
            );
          })
        ) : (
          <p className="px-4 py-6 text-sm text-muted">La liga no devolvió plantillas.</p>
        )}
      </div>

      <div className="mt-8">
        <ExtraBlock title="Clausulazos" count={offers.length} open={showOffers} onToggle={() => setShowOffers((value) => !value)}>
          <p className="mb-2 text-[11px] text-faint">{windowLabel(clauseIntel)}</p>
          {clauseIntelLoading && !clauseIntel ? (
            <p className="text-sm text-muted">Calculando…</p>
          ) : offers.length ? (
            <ul className="space-y-2">
              {offers.map((row) => (
                <li key={String(row.player_id)}>
                  <button
                    type="button"
                    className="flex w-full items-center justify-between gap-3 text-left"
                    onClick={() => row.team_id != null && setSelectedTeam(String(row.team_id))}
                  >
                    <span className="min-w-0 truncate text-sm text-ink">
                      {playerName(row)}
                      <span className="text-muted"> · {row.manager_name || ""}</span>
                    </span>
                    <span className="metric-value text-xs text-mint">
                      {typeof row.points_delta === "number" ? `+${points(row.points_delta)}` : eur(row.buyout_clause_eur)}
                    </span>
                  </button>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-sm text-muted">Ningún clausulazo mejora el XI ahora.</p>
          )}
        </ExtraBlock>
        <ExtraBlock title="Cláusulas interesantes" count={clauses.length} open={showClauses} onToggle={() => setShowClauses((value) => !value)}>
          {clauses.length ? (
            <ul className="space-y-2">
              {clauses.map((row) => (
                <li key={`${row.team_id}-${row.player_id}`}>
                  <button
                    type="button"
                    className="flex w-full items-center justify-between gap-3 text-left"
                    onClick={() => row.team_id != null && setSelectedTeam(String(row.team_id))}
                  >
                    <span className="min-w-0 truncate text-sm text-ink">
                      {playerName(row)}
                      <span className="text-muted"> · {row.manager_name || ""}</span>
                    </span>
                    <span className="metric-value text-xs">{eur(row.buyout_clause_eur)}</span>
                  </button>
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-sm text-muted">Ninguna cláusula cumple la regla de oro.</p>
          )}
        </ExtraBlock>
      </div>

      <RivalSheet
        squad={selectedSquad}
        isSelf={selectedTeam !== null && selectedTeam === ownTeamId}
        needs={needs}
        clauses={clauses}
        clauseOffers={selectedOffers}
        onClose={() => setSelectedTeam(null)}
      />
    </article>
  );
}
